values.value:
{
 "type": "object",
 "properties": {
  "explanations": {
   "type": "array",
   "items": {
    "type": "object",
    "properties": {
     "docId": {
      "type": "string"
     },
     "summary": {
      "type": "string",
      "description": "One sentence, max 30 words."
     },
     "criteria": {
      "type": "array",
      "items": {
       "type": "object",
       "properties": {
        "id": {
         "type": "string"
        },
        "met": {
         "type": "boolean"
        },
        "evidence": {
         "type": "string",
         "description": "Short quote or field from the input, or 'not on record'."
        },
        "source": {
         "type": "string",
         "description": "Where the evidence came from, as given in the input."
        }
       },
       "required": [
        "id",
        "met",
        "evidence"
       ]
      }
     }
    },
    "required": [
     "docId",
     "summary",
     "criteria"
    ]
   }
  }
 },
 "required": [
  "explanations"
 ]
}
